<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave} from 'vue-router'
import {ArrowLeft,Search,Plus,Database,ArrowUpRight,RotateCcw} from 'lucide-vue-next'
import {useLocal} from '../stores/local'
import type {Document} from '../domain/local-contract'
import type {VectorRecord,VectorDraft} from './vector-contract'
import {prepareVector,executeVector,saveVector,stopVector,recoverVector,nearestVectors,vectorPending,vectorDraft} from './vector-runtime'
const store=useLocal(),route=useRoute(),router=useRouter(),records=ref<Document<VectorRecord>[]>([]),draft=ref<Document<VectorDraft>|null>(null),input=ref(''),mode=ref<'index'|'query'>('query'),busy=ref(false),error=ref(''),notice=ref(''),query=ref<VectorRecord|null>(null),focused=ref<Document<VectorRecord>|null>(null),page=ref(0),draftDirty=ref(false)
const indexes=computed(()=>records.value.filter(row=>row.value.purpose==='index'&&row.value.status==='saved'&&!row.value.retired)),queries=computed(()=>records.value.filter(row=>row.value.purpose==='query'&&row.value.status==='saved'&&!row.value.retired).slice(0,10)),results=computed(()=>query.value?nearestVectors(query.value,records.value):[]),waiting=computed(()=>records.value.filter(row=>!row.value.retired&&row.value.status!=='saved').slice(0,50)),visible=computed(()=>indexes.value.slice(page.value*40,page.value*40+40))
const state={queued:'待开始',calling:'正在向量化',saved:'已保存',unknown:'响应未确认',cancelled:'已停止',failed:'未完成',persistence_failed:'等待保存'}
let disposed=false,loadEpoch=0,editVersion=0,savedVersion=0,writeQueue=Promise.resolve();const lifecycle=new AbortController()
function current(vault:typeof store.vault){return !disposed&&vault===store.vault&&!!vault?.unlocked}
async function load(){const vault=store.vault,epoch=++loadEpoch;if(!vault)return;const all=(await vault.list<VectorRecord>('settings')).filter(row=>row.value.assetType==='embedding-record');const rows:Document<VectorRecord>[]=[];for(const row of all)rows.push(await recoverVector(vault,row));if(current(vault)&&epoch===loadEpoch)records.value=rows.sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt))}
function writeDraft(){const value=input.value,version=editVersion;writeQueue=writeQueue.then(async()=>{const vault=store.vault,row=draft.value;if(!vault||!row||!current(vault))return;if(row.value.input!==value)await vault.commitBundle(crypto.randomUUID(),[{kind:'settings',id:row.id,expectedRevision:row.revision,value:{...row.value,input:value}}],lifecycle.signal);if(current(vault)){draft.value=(await vault.read<VectorDraft>(row.id))!;savedVersion=version;draftDirty.value=savedVersion!==editVersion}}).catch(e=>{if(!disposed){error.value=(e as Error).message;draftDirty.value=true}});return writeQueue}
function edited(){editVersion++;draftDirty.value=true;void writeDraft()}
function beforeUnload(event:BeforeUnloadEvent){if(draftDirty.value){event.preventDefault();event.returnValue=''}}
onBeforeRouteLeave(async()=>{await writeDraft();return !draftDirty.value})
async function run(){const vault=store.vault;if(!vault||busy.value||!input.value.trim())return;busy.value=true;error.value='';notice.value='';try{await writeDraft();const row=await prepareVector(vault,input.value,mode.value==='index'?draft.value?.value.source||null:null,lifecycle.signal,mode.value);if(!current(vault))return;await load();const saved=row.value.status==='saved'?row:await executeVector(vault,row.id);if(!current(vault))return;await load();if(mode.value==='query')query.value=saved.value;else{const head=draft.value;if(head){await vault.commitBundle(crypto.randomUUID(),[{kind:'settings',id:head.id,expectedRevision:head.revision,value:{...head.value,input:'',source:null}}],lifecycle.signal);if(!current(vault))return;draft.value=(await vault.read<VectorDraft>(head.id))!;input.value=''}notice.value='已保存到索引'}}catch(e){if(current(vault)){error.value=(e as Error).message;await load().catch(()=>{})}}finally{if(current(vault))busy.value=false}}
async function act(row:Document<VectorRecord>,action:'save'|'stop'|'start'|'retire'){const vault=store.vault;if(!vault||busy.value&&action!=='stop')return;const wasBusy=busy.value;busy.value=true;error.value='';try{if(action==='save')await saveVector(vault,row.id);else if(action==='stop')await stopVector(vault,row.id);else if(action==='start')await executeVector(vault,row.id);else{const head=await vault.read<VectorRecord>(row.id);if(head)await vault.commit(crypto.randomUUID(),'settings',row.id,head.revision,{...head.value,retired:true,updatedAt:new Date().toISOString()})}if(current(vault))await load()}catch(e){if(current(vault))error.value=(e as Error).message}finally{if(current(vault)&&!wasBusy)busy.value=false}}
function sourcePath(row:Document<VectorRecord>){const source=row.value.source;if(!source)return null;if(source.targetKind==='story')return {path:'/local/read/'+source.targetId,query:{branch:source.branchId||undefined,paragraph:source.paragraphId}};if(source.targetKind==='card')return {path:'/local/characters'};if(source.targetKind==='session')return {path:'/local/chat/'+source.targetId};return null}
function view(row:Document<VectorRecord>){query.value=row.value;input.value=row.value.input;mode.value='query';notice.value='';error.value='';edited()}
function changed(){void load().catch(e=>{if(!disposed)error.value=(e as Error).message})}
onMounted(async()=>{window.addEventListener('beforeunload',beforeUnload);window.addEventListener('reader-vector-changed',changed);try{const vault=store.vault;if(!vault)return;if(typeof route.query.record==='string'){await load();if(!current(vault))return;const wanted=records.value.find(row=>row.id===route.query.record);if(!wanted)throw Error('这份索引记录已删除或无法打开');focused.value=wanted;if(wanted.value.purpose==='query'&&wanted.value.vector)query.value=wanted.value;return}const id=typeof route.query.draft==='string'?route.query.draft:null;if(id){const row=await vault.read<VectorDraft>(id);if(!row||row.value.assetType!=='vector-draft')throw Error('这个索引草稿已失效');if(!current(vault))return;draft.value=row;input.value=row.value.input;if(row.value.source)mode.value='index'}else{const destination=await vectorDraft(vault,'',null,lifecycle.signal);if(current(vault))await router.replace(destination);return}await load()}catch(e){if(!disposed)error.value=(e as Error).message}})
onUnmounted(()=>{disposed=true;lifecycle.abort();window.removeEventListener('beforeunload',beforeUnload);window.removeEventListener('reader-vector-changed',changed);records.value=[];query.value=null;draft.value=null;input.value=''})
</script>
<template>
  <section class="final-vectors">
    <div class="final-page-heading"><div class="final-heading-copy"><RouterLink to="/local/settings" class="final-text-link"><ArrowLeft :size="17"/>我的</RouterLink><h1>内容索引</h1><RouterLink v-if="!draft" to="/local/vectors" class="final-text-link">新建索引</RouterLink></div><RouterLink to="/local/settings/media" class="final-text-link">向量通道<ArrowUpRight :size="16"/></RouterLink></div>
    <p v-if="error" role="alert" class="final-error">{{error}}</p><p v-if="notice" role="status" class="final-subtle">{{notice}}</p>
    <article v-if="focused" class="final-setting-card" aria-label="所选索引记录"><strong>{{state[focused.value.status]}}</strong><p>{{focused.value.input}}</p><small>{{focused.value.configSnapshot.modelId}} · {{focused.value.vector?.length||0}} 维</small><button v-if="!focused.value.historical&&['queued','calling','persistence_failed'].includes(focused.value.status)" :disabled="busy" @click="act(focused,'stop')">停止</button></article><div class="final-vector-layout">
      <div>
        <form v-if="draft" class="final-vector-form" @submit.prevent="run">
          <div class="final-vector-tabs" role="group" aria-label="索引用途"><button type="button" :disabled="busy" :aria-pressed="mode==='query'" @click="mode='query';query=null"><Search :size="18"/>查找内容</button><button type="button" :disabled="busy" :aria-pressed="mode==='index'" @click="mode='index';query=null"><Plus :size="18"/>保存索引</button></div>
          <label>{{mode==='query'?'想找什么？':'保存一段内容'}}<textarea v-model="input" aria-label="索引文本" :disabled="busy" maxlength="8000" rows="6" @input="edited" @blur="writeDraft" :placeholder="mode==='query'?'用自己的话描述记得的情节、人物或设定':'粘贴正文、角色设定或笔记'"/></label>
          <div class="final-vector-submit"><span class="final-subtle">{{draftDirty?'草稿保存中 · ':''}}{{input.length.toLocaleString()}} / 8,000</span><button class="final-primary" :disabled="busy||!draft||!input.trim()"><component :is="mode==='query'?Search:Database" :size="18"/>{{busy?'正在处理…':mode==='query'?'查找':'保存这段'}}</button></div>
          <small v-if="draft?.value.source" class="final-subtle">已关联所选正文</small>
        </form>
        <div v-if="query" class="final-vector-results" aria-live="polite"><h2>相近内容</h2><p v-if="!results.length" class="final-subtle">当前通道还没有可匹配的索引。</p><article v-for="hit in results" :key="hit.row.id" class="final-vector-item"><div><span class="final-vector-score">{{Math.round(hit.score*100)}}%</span><RouterLink v-if="sourcePath(hit.row)" :to="sourcePath(hit.row)!" class="final-text-link">回到原文<ArrowUpRight :size="16"/></RouterLink></div><p>{{hit.row.value.input}}</p></article></div>
        <div v-if="waiting.length" class="final-vector-results"><h2>请求记录</h2><article v-for="row in waiting" :key="row.id" class="final-vector-item"><div><strong>{{state[row.value.status]}}</strong><small>{{row.value.configSnapshot.modelId}}</small></div><p>{{row.value.input.slice(0,200)}}</p><p v-if="row.value.error" class="final-subtle">{{row.value.error}}</p><div class="final-grid-actions"><button v-if="vectorPending(store.vault!,row.id)" :disabled="busy" @click="act(row,'save')">只重试保存</button><button v-else-if="row.value.status==='queued'&&!row.value.historical" :disabled="busy" @click="act(row,'start')">开始这次请求</button><button v-if="['queued','calling','persistence_failed'].includes(row.value.status)" @click="act(row,'stop')">停止</button><button v-if="row.value.status!=='calling'" :disabled="busy" @click="act(row,'retire')">收起记录</button></div></article></div>
      </div>
      <aside class="final-vector-collection"><div class="final-vector-title"><h2>已保存</h2><span class="final-subtle">{{indexes.length}}</span></div><p v-if="!indexes.length" class="final-subtle">从阅读页选一段，或在这里保存。</p><article v-for="row in visible" :key="row.id" class="final-vector-item"><p>{{row.value.input.slice(0,220)}}</p><div><small>{{row.value.vector?.length}} 维 · {{row.value.configSnapshot.modelId}}</small><button class="final-vector-remove" :disabled="busy" @click="act(row,'retire')">移出索引</button></div></article><div v-if="indexes.length>40" class="final-grid-actions"><button :disabled="page===0" @click="page--">上一页</button><button :disabled="(page+1)*40>=indexes.length" @click="page++">下一页</button></div><template v-if="queries.length"><h2>最近查找</h2><button v-for="row in queries" :key="row.id" class="final-vector-recent" @click="view(row)"><RotateCcw :size="15"/><span>{{row.value.input.slice(0,70)}}</span></button></template></aside>
    </div>
  </section>
</template>
<style scoped>
.final-vector-layout{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(250px,1fr);gap:28px;align-items:start}.final-vector-form,.final-vector-collection{background:var(--paper);border:1px solid var(--edge);border-radius:18px;padding:24px}.final-vector-tabs{display:flex;gap:8px;margin-bottom:24px}.final-vector-tabs button[aria-pressed=true]{background:var(--accent-soft);color:var(--accent);border-color:var(--accent)}.final-vector-form label{display:grid;gap:12px}.final-vector-form textarea{resize:vertical;min-height:160px}.final-vector-submit,.final-vector-title,.final-vector-item>div{display:flex;align-items:center;justify-content:space-between;gap:12px}.final-vector-submit{margin-top:16px}.final-vector-collection h2,.final-vector-results h2{font:500 22px var(--font-serif);margin:0 0 20px}.final-vector-results{margin-top:32px}.final-vector-item{border-bottom:1px solid var(--edge);padding:20px 0}.final-vector-item:first-of-type{padding-top:0}.final-vector-item p{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.8;font-size:15px}.final-vector-item small{font-size:12px;color:var(--muted);overflow-wrap:anywhere}.final-vector-score{font-size:12px;color:var(--accent);border:1px solid var(--edge);border-radius:30px;padding:4px 10px}.final-vector-remove{font-size:12px;white-space:nowrap}.final-vector-recent{display:flex;gap:10px;text-align:left;width:100%;margin:8px 0}.final-vector-recent span{overflow-wrap:anywhere}.final-vector-collection>h2{margin-top:28px}@media(max-width:800px){.final-vector-layout{grid-template-columns:1fr;gap:24px}.final-vector-form,.final-vector-collection{padding:20px}.final-vector-tabs button{flex:1;justify-content:center}.final-vector-item>div{flex-wrap:wrap}}
</style>
